cd /app && cat > prep.py <<'EOF'
import pyarrow.parquet as pq, re, html
tok = re.compile(r"[\w']+|[.,!?;:()\"$%&/-]")
def norm(t):
    t = html.unescape(t).replace('\\n',' ').replace('\\"','"')
    return ' '.join(tok.findall(t.lower()))
for split,src in [('train','data/train-00000-of-00001.parquet'),('test','data/test-00000-of-00001.parquet')]:
    f=pq.ParquetFile(src)
    with open(f'{split}.txt','w') as out:
        for b in f.iter_batches(batch_size=20000, columns=['label','text']):
            d=b.to_pydict()
            for l,t in zip(d['label'],d['text']):
                out.write(f'__label__{l} {norm(t)}\n')
EOF
python3 prep.py && wc -l train.txt test.txt && head -c 400 train.txt && du -sh train.txt
